#!/bin/sh
# Root dropbear installer for the GoPro HERO11 (H22.01.02.20.00).
#
# gpNet runs this file as root when it receives the BP command "SC" with
# payload byte 0x02:
#     curl 'http://<camera>/gp/gpCamera?cmd=SC&p=%02'
#
# It runs from the ROOT of the SD card, next to:
#     dropbearmulti     static aarch64 dropbear (see README-BUILD.md)
#     dropbear.conf     AUTH=blank|password|keyonly (scripts/install-card.sh)
#     authorized_keys   optional public key(s)
#     root_hash         optional, password mode only
#     dropbear_hostkey  optional, generated by scripts/install-card.sh
#
# Everything is logged to /tmp/fuse_d/DROPBEAR_LOG.txt, so a failed run is
# diagnosable from the card alone.
PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin
export PATH
# gpNet runs us with an unrestricted umask; a 0777 state dir makes dropbear
# refuse authorized_keys, silently.
umask 022

CARD=/tmp/fuse_d
LOG=$CARD/DROPBEAR_LOG.txt
PORT=22
IPT=/usr/sbin/iptables
[ -x "$IPT" ] || IPT=/sbin/iptables

# Auth mode, written to the card by scripts/install-card.sh. Missing or bad
# means the default: blank password (dropbear -B) against the camera's empty
# root hash. "password" uses root_hash via a shadow bind mount; "keyonly" is -s.
AUTH=blank
if [ -r "$CARD/dropbear.conf" ]; then
    conf_auth=$(sed -n 's/^AUTH=//p' "$CARD/dropbear.conf" 2>/dev/null | tail -n 1)
    case "$conf_auth" in
        blank|password|keyonly) AUTH=$conf_auth ;;
    esac
fi

log() { echo "$(date '+%F %T' 2>/dev/null) $*" >> "$LOG"; }

# Diagnostic channel: GET a unique path per step, so the progress is visible in
# the build host's HTTP access log even when the camera cannot push anything
# itself. Cheap, and it only needs the one outbound path we know works.
# scheduled_capture.sh discovers this address (USB peer or Wi-Fi DHCP client)
# and exports it; the USB address is the default when this runs standalone.
HOST="${HOST:-172.23.148.52}"
HTTP_PORT=8000
beacon() {
    enc=$(echo "$*" | sed 's/%/%25/g; s/ /%20/g; s/#/%23/g; s/?/%3F/g; s/"/%22/g; s#/#%2F#g')
    /usr/bin/wget -q -T 3 -O /dev/null "http://$HOST:$HTTP_PORT/beacon/$enc" 2>/dev/null
}
# Replay the collected log over the same channel, one line per request.
exfil() {
    grep -v '^$' "$LOG" 2>/dev/null | head -n 200 | while IFS= read -r line; do
        beacon "LOG: $line"
    done
}

if [ ! -d "$CARD" ]; then
    echo "fuse_d not mounted" > /tmp/DROPBEAR_LOG.txt 2>&1
    exit 1
fi

log "=== dropbear install: $(date 2>/dev/null) ==="
beacon "stage-start"

# Each probe gets its own beacon and a timeout, so a hang on one (df on a
# wedged FUSE mount is the obvious candidate) is visible and survivable.
envdump() {
    label=$1
    shift
    { echo "--- $label"; timeout 5 "$@" 2>&1; } >> "$LOG" 2>&1
    beacon "env-$label"
}
envdump uname uname -a
envdump cmdline cat /proc/cmdline
envdump mounts cat /proc/mounts
envdump df df -h
envdump iptables "$IPT" -S
envdump ids id
envdump listeners netstat -ltn

{
    echo "--- writable"
    for d in / /usr/local/gopro /home/root /run /var/run /dev; do
        if touch "$d/.wtest" 2>/dev/null; then echo "$d rw"; rm -f "$d/.wtest"
        else echo "$d ro-or-missing"; fi
    done
} >> "$LOG" 2>&1
beacon "env-writable"

# dropbear's checkpubkeyperms() rejects authorized_keys when ANY ancestor
# directory is group- or world-writable. /run and /tmp are bare tmpfs, which
# the kernel defaults to 1777, so they are unusable for -D. /dev is the one rw
# filesystem mounted with an explicit mode=755.
perm_violation() {   # prints the offending ancestor, or nothing
    p=$1
    while [ -n "$p" ] && [ "$p" != "/" ]; do
        mode=$(ls -ld "$p" 2>/dev/null)
        if [ -n "$mode" ]; then
            grp=$(echo "$mode" | cut -c6)
            oth=$(echo "$mode" | cut -c9)
            # 1777 shows as 't' in the other-execute slot (sticky + write).
            if [ "$grp" = "w" ] || [ "$oth" = "w" ] || [ "$oth" = "t" ] || [ "$oth" = "T" ]; then
                echo "$p ($(echo "$mode" | cut -c1-10))"
                return 0
            fi
        fi
        p=$(dirname "$p")
    done
    return 0
}

STATE=""
for d in /dev/dropbear /run/dropbear /var/run/dropbear /home/root/.ssh /usr/local/gopro/dropbear; do
    beacon "try=$d"
    mkdir -p "$d" 2>/dev/null || { beacon "mkdir-fail=$d"; continue; }
    chmod 700 "$d" 2>/dev/null
    beacon "mode=$d:$(ls -ld "$d" 2>/dev/null | cut -c1-10):parent=$(ls -ld "$(dirname "$d")" 2>/dev/null | cut -c1-10)"
    if touch "$d/.wtest" 2>/dev/null; then rm -f "$d/.wtest"; else beacon "notwritable=$d"; continue; fi
    bad=$(perm_violation "$d")
    if [ -n "$bad" ]; then
        log "skip $d: ancestor $bad is group/world-writable (dropbear would refuse the key)"
        beacon "perm-skip=$d"
        continue
    fi
    STATE=$d
    break
done

# Last resort: make a tmpfs parent acceptable rather than give up. This only
# removes group/other write, and only if nothing safer was writable.
if [ -z "$STATE" ]; then
    for d in /run/dropbear /var/run/dropbear; do
        [ -d "$(dirname "$d")" ] || continue
        chmod go-w "$(dirname "$d")" 2>/dev/null || continue
        log "hardened $(dirname "$d") to $(ls -ld "$(dirname "$d")" 2>/dev/null | cut -c1-10)"
        mkdir -p "$d" 2>/dev/null || continue
        if touch "$d/.wtest" 2>/dev/null && [ -z "$(perm_violation "$d")" ]; then
            rm -f "$d/.wtest"
            STATE=$d
            break
        fi
    done
fi

if [ -z "$STATE" ]; then
    log "FATAL: no permission-safe writable state directory"
    beacon "fatal-no-state"
    exfil
    exit 1
fi
chmod 700 "$STATE" 2>/dev/null
beacon "state=$STATE"
log "state dir: $STATE (parent $(dirname "$STATE"): $(ls -ld "$(dirname "$STATE")" 2>/dev/null | cut -c1-10))"

# The card is a FUSE mount; the binary has to live on a local filesystem.
if ! cp "$CARD/dropbearmulti" "$STATE/dropbearmulti" 2>>"$LOG"; then
    log "FATAL: cannot copy dropbearmulti"
    exit 1
fi
chmod 755 "$STATE/dropbearmulti"

# Prove the binary executes here before relying on it (ABI/exec check).
if ! "$STATE/dropbearmulti" dropbear -V >> "$LOG" 2>&1; then
    log "FATAL: dropbearmulti does not execute in $STATE"
    exit 1
fi

# The password-enabled build is what provides -B (blank login) and -s. A card
# staged with the old key-only binary cannot honour dropbear.conf.
if ! "$STATE/dropbearmulti" dropbear -h 2>&1 | grep -q -- '-B'; then
    log "FATAL: binary has no password support; re-run scripts/install-card.sh"
    beacon "fatal-old-binary"
    exfil
    exit 1
fi
beacon "auth=$AUTH"

# Password mode: override root's hash without touching the read-only rootfs.
# A stale overlay from an earlier run must go, or a blank login would see a
# non-empty hash and fail.
if [ "$AUTH" = password ]; then
    if [ ! -s "$CARD/root_hash" ]; then
        log "FATAL: AUTH=password but no root_hash on the card"
        beacon "fatal-no-root-hash"; exfil; exit 1
    fi
    root_hash=$(head -n 1 "$CARD/root_hash" 2>/dev/null)
    if ! cp /etc/shadow /tmp/shadow.dropbear 2>>"$LOG"; then
        log "FATAL: cannot read /etc/shadow"
        beacon "fatal-shadow-read"; exfil; exit 1
    fi
    awk -F: -v OFS=: -v h="$root_hash" '$1=="root" { $2=h } { print }' \
        /tmp/shadow.dropbear > /tmp/shadow.dropbear.new 2>>"$LOG"
    if ! grep -q '^root:' /tmp/shadow.dropbear.new 2>/dev/null; then
        log "FATAL: root entry missing from the generated shadow"
        beacon "fatal-shadow-root"; exfil; exit 1
    fi
    chmod 600 /tmp/shadow.dropbear.new 2>/dev/null
    umount /etc/shadow 2>/dev/null
    if ! mount --bind /tmp/shadow.dropbear.new /etc/shadow >> "$LOG" 2>&1; then
        log "FATAL: cannot bind-mount the password shadow over /etc/shadow"
        beacon "fatal-shadow-mount"; exfil; exit 1
    fi
    log "auth: password (shadow overridden from root_hash)"
else
    if grep -q ' /etc/shadow ' /proc/mounts 2>/dev/null; then
        umount /etc/shadow 2>/dev/null && log "auth: removed a previous shadow overlay"
    fi
    log "auth: $AUTH"
fi

# Keys are optional now: blank and password modes work without them.
if [ -s "$CARD/authorized_keys" ]; then
    if cp "$CARD/authorized_keys" "$STATE/authorized_keys" 2>>"$LOG"; then
        chmod 600 "$STATE/authorized_keys" 2>/dev/null
        beacon "keys-installed"
        log "authorized_keys: $(wc -c < "$STATE/authorized_keys" 2>/dev/null) bytes"
    else
        log "WARN: cannot copy authorized_keys"
    fi
else
    rm -f "$STATE/authorized_keys"
    log "authorized_keys: none on the card"
fi
if [ "$AUTH" = keyonly ] && [ ! -s "$STATE/authorized_keys" ]; then
    log "FATAL: AUTH=keyonly but no usable authorized_keys"
    beacon "fatal-no-keys"
    exfil
    exit 1
fi

# Stable host identity: keep an existing key, else take the one shipped on the
# card, else generate one and put it back on the card for the next boot.
if [ -s "$STATE/hostkey" ]; then
    :
elif [ -s "$CARD/dropbear_hostkey" ]; then
    cp "$CARD/dropbear_hostkey" "$STATE/hostkey"
elif "$STATE/dropbearmulti" dropbearkey -t ed25519 -f "$STATE/hostkey" >> "$LOG" 2>&1; then
    cp "$STATE/hostkey" "$CARD/dropbear_hostkey" 2>/dev/null
else
    log "FATAL: no host key and dropbearkey failed"
    exit 1
fi
chmod 600 "$STATE/hostkey" 2>/dev/null

# Inbound is DROP by default; open only this port. gpNet itself inserts its
# TFTP rule the same way (iptables -I INPUT 1 ...).
if "$IPT" -C INPUT -p tcp --dport "$PORT" -j ACCEPT >/dev/null 2>&1; then
    log "iptables: accept tcp/$PORT already present"
elif "$IPT" -I INPUT 1 -p tcp --dport "$PORT" -j ACCEPT >> "$LOG" 2>&1; then
    log "iptables: inserted accept tcp/$PORT at INPUT 1"
else
    log "WARN: could not insert the iptables rule; ssh may be filtered"
fi

# Auth flags: blank = -B (log in with no password), keyonly = -s (no password
# auth at all), password = neither (the card's hash is the shadow override).
# Always restart: a stale instance from an earlier run would keep serving the
# old -D directory and hide a bad configuration.
beacon "about-to-start"
killall dropbearmulti 2>/dev/null
sleep 1
killall -9 dropbearmulti 2>/dev/null
sleep 1
: > /tmp/dropbear.log
set -- -r "$STATE/hostkey" -D "$STATE" -p "0.0.0.0:$PORT" -E
case "$AUTH" in
    blank)   set -- -B "$@" ;;
    keyonly) set -- -s "$@" ;;
esac
"$STATE/dropbearmulti" dropbear "$@" >> /tmp/dropbear.log 2>&1 &
sleep 2

{
    echo "--- state dir";       ls -ld "$STATE" "$STATE"/authorized_keys "$STATE"/hostkey "$STATE"/dropbearmulti
    echo "--- ancestors";       for a in $(dirname "$STATE") /; do ls -ld "$a"; done
    echo "--- key content";     cat "$STATE/authorized_keys" 2>/dev/null
    echo "--- ps";              ps 2>/dev/null | grep -i dropbear
    echo "--- listeners";       netstat -ltn
    echo "--- dropbear stderr"; cat /tmp/dropbear.log 2>/dev/null
} >> "$LOG" 2>&1

if netstat -ltn 2>/dev/null | grep -q ":$PORT "; then
    log "OK: dropbear listening on :$PORT (state=$STATE)"
    mkdir -p "$CARD/DCIM/100GOPRO" 2>/dev/null
    cp "$LOG" "$CARD/DCIM/100GOPRO/DROPBEAR_LOG.TXT" 2>/dev/null
    echo "dropbear up $(date 2>/dev/null) state=$STATE" \
        > "$CARD/DCIM/100GOPRO/DROPBEAR_OK.TXT" 2>/dev/null
    exfil
    exit 0
fi

log "FAIL: no listener on :$PORT"
cp "$LOG" "$CARD/DCIM/100GOPRO/DROPBEAR_LOG.TXT" 2>/dev/null
exfil
exit 1
